from taf.rfrl.procedures.resources.python.status_check.cells.NR_cell import NrCell
from taf.rfrl.procedures.resources.python.status_check.cells.LTE_cell import LteCell
from taf.rfrl.procedures.resources.python.status_check.cells.WCDMA_cell import WcdmaCell
from taf.rfrl.procedures.resources.python.status_check.cells.GSM_cell import GsmCell


class CellFactory:
    """
    Creates NrCell, LteCell, WcdmaCell or GsmCell instances depending on cell_type
    """

    @staticmethod
    def create_cell(cell_type, status_variant, connection, cell_id=None):
        """
        Creates Cell instance
        :param cell_type: type of cells, can be "nr", "lte", "wcdma" or "gsm"
        :type cell_type: str
        :param status_variant: variant of cells status, can be: active, online, blocked, failed or dependency
        :type status_variant: str
        :param connection: connection name (i.e. 'admin' or 'lte') or connection object if used
        :type connection: str or AdminConnection
        :param cell_id: ID of cell, default to None, e.g. 2
        :type cell_id: Union[int, str]
        :return: NrCell, LteCell, WcdmaCell or GsmCell instance
        :rtype: Cell
        """
        if cell_type == "nr":
            return NrCell(variant=status_variant, connection=connection, cell_id=cell_id)
        elif cell_type == "lte":
            return LteCell(variant=status_variant, connection=connection, cell_id=cell_id)
        elif cell_type == "wcdma":
            return WcdmaCell(variant=status_variant, connection=connection)
        elif cell_type == "gsm":
            return GsmCell(variant=status_variant, connection=connection)
